#!/bin/sh
set -eu
[ "$#" -eq 1 ] || { echo "usage: ROLLBACK.sh TARGET_COPY" >&2; exit 2; }
python3 - "$1" <<'PYROLLBACK'
import base64,hashlib,sys
from pathlib import Path
p=Path(sys.argv[1])
if p.is_symlink() or not p.is_file():
    raise SystemExit('refuse non-file or symlink')
expected='b52649a98a85d3e95fb13b77a7b00cb9cbc66a7a0c6b06776e477141d0e848a8'
if hashlib.sha256(p.read_bytes()).hexdigest()!=expected:
    raise SystemExit('refuse unexpected target bytes')
b=base64.b64decode('')
assert hashlib.sha256(b).hexdigest()=='62b5b050a3f1a2916e289b2350514eb963a1d0543e54c0815347ed1af8c40988'
p.write_bytes(b)
print('restored_sha256='+hashlib.sha256(p.read_bytes()).hexdigest())
PYROLLBACK
